    27 |     calls += 1;
    28 |     if calls < 3 {
    29 |         Err(RetryError::Transient("temporary outage".into()))
    30 |     } else {
    31 |         Ok(())
    32 |     }
    33 | });
    34 | assert!(result.is_ok());
